create policy "insert own notes" on notes
for insert to authenticated
with check ( (select auth.uid()) = user_id );

create policy "update own notes" on notes
for update to authenticated
using ( (select auth.uid()) = user_id )
with check ( (select auth.uid()) = user_id );

create policy "read own or shared notes"
on notes for select to authenticated
using (
  (select auth.uid()) = user_id
  or exists (
    select 1 from note_shares s
    where s.note_id = notes.id
      and s.shared_with = (select auth.uid())
  )
);
